  "Remove guest?": {"res": "Settings:user_exit_guest_confirm_title", "hu": "Eltávolítja a vendég munkamenetet?", "de": "Gast entfernen?", "fr": "Supprimer l'invité ?", "es": "¿Eliminar invitado?"},
  "All apps and data in this session will be deleted.": {"res": "Settings:user_exit_guest_confirm_message", "hu": "A munkamenetben található összes alkalmazás és adat törlődni fog.", "de": "Alle Apps und Daten in dieser Sitzung werden gelöscht.", "fr": "Toutes les applications et les données de cette session seront supprimées.", "es": "Se eliminarán las aplicaciones y los datos de esta sesión."},
